    public static void test_extract_links_formatting() {
        var result = load_mock_page(
                "http://www.pcgamer.com/2012/08/09/skyrim-part-1/",
                /* formatting = */ true,
                /* links = */ true);
        assert result.contains("In [Skyrim](https://www.pcgamer.com/best-skyrim-mods/), a mage");
        // the source has a trailing space inside the em tag; it must stay outside the markers (valid CommonMark)
        assert result.contains("*Legends* don't destroy *houses*,");
    }

